package com.peopleai.contact.controller;
import com.fasterxml.jackson.databind.ObjectMapper;import com.peopleai.contact.model.Lead;import com.peopleai.contact.repository.LeadRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.Email;import jakarta.validation.constraints.NotBlank;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/contact") @CrossOrigin(origins="*") public class ContactController{private final LeadRepository repo;private final KafkaTemplate<String,String> kafka;private final ObjectMapper json;public ContactController(LeadRepository r,KafkaTemplate<String,String> k,ObjectMapper j){repo=r;kafka=k;json=j;}@PostMapping("/lead")@ResponseStatus(HttpStatus.CREATED)public Map<String,Object> submit(@Valid @RequestBody LeadRequest x)throws Exception{Lead l=repo.save(new Lead(x.name(),x.email(),x.company(),x.message()));String event=json.writeValueAsString(Map.of("id",l.getId(),"email",l.getEmail(),"company",l.getCompany(),"createdAt",l.getCreatedAt().toString()));kafka.send("peopleai.leads.submitted",String.valueOf(l.getId()),event);return Map.of("success",true,"message","Request received. Our team will contact you shortly.","lead",Map.of("id",l.getId(),"name",l.getName(),"email",l.getEmail(),"company",l.getCompany(),"status",l.getStatus()));}public record LeadRequest(@NotBlank String name,@NotBlank @Email String email,@NotBlank String company,@NotBlank String message){}}
